stick.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);stickMove(e);});stick.addEventListener('pointermove',e=>{if(stickPointer===e.pointerId)stickMove(e);});for(const ev of ['pointerup','pointercancel'])stick.addEventListener(ev,()=>{stickPointer=null;input.stick={x:0,z:0};$('#stick-knob').style.transform='';});document.querySelectorAll('[data-move]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();held.add(b.dataset.move);input.target=null;b.setPointerCapture(e.pointerId);});for(const ev of ['pointerup','pointercancel'])b.addEventListener(ev,()=>held.delete(b.dataset.move));b.addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();held.add(b.dataset.move);}});b.addEventListener('keyup',()=>held.delete(b.dataset.move));});
// Cache actual rendered scenes once per release; no missing images for newly added games.
async function generatePreviews(missing=null){world.thumbnail=true;world.renderer.setSize(560,340,false);world.camera.aspect=560/340;world.camera.fov=52;world.camera.updateProjectionMatrix();const requested=new URLSearchParams(location.search).get('generate-previews'),games=missing|| (requested?catalogue.filter(g=>requested.split(',').includes(g.id)):catalogue);for(let i=0;i<games.length;i++){const g=games[i];$('#loading-text').textContent=`Preparing ${g.name} preview… ${i+1}/${games.length}`;const m=createMode({world,input:idleInput,ui:quietUI,game:g,settings});for(const a of m.actors)animateActor(a,0,0,a.userData.pose||'idle',0);if(['pampanaa','shooting','pilolo'].includes(g.id))world.setCamera([17,16,23,-1,0,0],true);world.render(0,0);thumbs.set(g.id,canvas.toDataURL('image/jpeg',.88));m.dispose();if(i%4===0)await new Promise(requestAnimationFrame);}world.thumbnail=false;}
async function boot(){try{await document.fonts.ready;$('#loading-text').textContent='Loading players, clothing and photographed surfaces…';await Promise.all([loadAthletes((n,total)=>$('#loading-text').textContent=`Preparing players… ${n}/${total}`),loadSurfaces(),loadFootballAssets(),soundscape.preload()]);world=new World(canvas);await world.loadSky();applySettings();const cached=await readPreviews(catalogue.map(g=>g.id));for(const [id,src]of cached)thumbs.set(id,src);const missing=catalogue.filter(g=>!thumbs.has(g.id));if(missing.length){await generatePreviews(missing);await savePreviews(thumbs);}if(location.hostname==='127.0.0.1'&&new URLSearchParams(location.search).has('generate-previews'))await generatePreviews();world.resize();$('#loading').hidden=true;lobby();const params=new URLSearchParams(location.search);if(params.has('game')){openSetup(gameById(params.get('game')));}else{$('#lobby').hidden=true;$('#launch-screen').hidden=false;document.body.classList.add('in-launch');}requestAnimationFrame(frame);}catch(error){console.error('Unable to initialise arcade',error);$('#loading').hidden=true;$('#webgl-error').hidden=false;}}
function frame(now){const dt=Math.min(.05,Math.max(0,(now-last)/1000));last=now;if(!document.hidden){elapsed+=dt;if(state==='playing'){const steps=Math.max(1,Math.ceil(dt/(1/60)));for(let i=0;i<steps;i++)active?.tick(dt/steps,elapsed-dt+(i+1)*dt/steps);}else if(state==='lobby'&&demo){for(const a of demo.actors)animateActor(a,elapsed,0);if(!matchMedia('(prefers-reduced-motion: reduce)').matches){world.desired.x=-14+Math.sin(elapsed*.04)*2;world.desired.z=14+Math.cos(elapsed*.04)*2;}}world.render(dt,elapsed);}requestAnimationFrame(frame);}
document.querySelectorAll('[data-replay]').forEach(b=>{b.disabled=!replay.supported();b.onclick=async()=>{const url=await replay.finish();if(!url)return;$('#replay-video').src=url;$('#save-replay').href=url;$('#save-replay').download='ghana-street-games-replay.'+replay.extension();soundscape.setScene('replay');$('#replay-dialog').showModal();$('#replay-video').play().catch(()=>{});};});$('#replay-dialog').addEventListener('close',()=>{$('#replay-video').pause();soundscape.setScene(state==='lobby'?'menu':state==='playing'?'game':state,active?.venue?.kind||'pitch');});
boot();
